# -*- coding: utf-8 -*-
# 第 10 批（C2）：水污染防治法（107/6/13）第40條～第75條
W = "ENV-07"
Q = [

(W,"第40條",3,"水污法-罰則",
 "事業排放廢（污）水違反放流水標準或污泥處理規定者，罰鍰額度為何？畜牧業呢？",
 ["事業或污水下水道系統處新臺幣六萬元以上二千萬元以下罰鍰；畜牧業處新臺幣六千元以上六十萬元以下罰鍰，均通知限期改善並得按次處罰","事業或污水下水道系統處新臺幣三萬元以上三百萬元以下罰鍰；畜牧業處新臺幣一萬元以上一百萬元以下罰鍰，均通知限期改善並得按次處罰","事業或污水下水道系統處新臺幣六萬元以上六百萬元以下罰鍰；畜牧業處新臺幣三千元以上三十萬元以下罰鍰，均通知限期改善並得按次處罰","事業或污水下水道系統處新臺幣一萬元以上六百萬元以下罰鍰；畜牧業處新臺幣六萬元以上二千萬元以下罰鍰，均通知限期改善並得按次處罰"],"a",
 "第40條第1項：事業或污水下水道系統排放廢（污）水違反第7條第1項或第8條規定者，處新臺幣六萬元以上二千萬元以下罰鍰。第2項：畜牧業違反者處新臺幣六千元以上六十萬元以下罰鍰。二者均通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停工或停業，必要時得廢止許可證（文件）或勒令歇業。",
 "What fines apply to enterprises breaching effluent standards or sludge rules, and to livestock farms?",
 ["Enterprises and sewer systems NT$60,000 to NT$20,000,000; livestock farms NT$6,000 to NT$600,000, both with an improvement deadline and consecutive penalties","Enterprises and sewer systems NT$30,000 to NT$3,000,000; livestock farms NT$10,000 to NT$1,000,000, both with an improvement deadline and consecutive penalties","Enterprises and sewer systems NT$60,000 to NT$6,000,000; livestock farms NT$3,000 to NT$300,000, both with an improvement deadline and consecutive penalties","Enterprises and sewer systems NT$10,000 to NT$6,000,000; livestock farms NT$60,000 to NT$20,000,000, both with an improvement deadline and consecutive penalties"],
 "Article 40, paragraphs 1 and 2."),

(W,"第41條",2,"水污法-建築物設施罰則",
 "建築物污水處理設施違反第七條第一項或第八條規定者，罰鍰額度為何？",
 ["處新臺幣三千元以上三十萬元以下罰鍰","處新臺幣六萬元以上二千萬元以下罰鍰","處新臺幣六千元以上六十萬元以下罰鍰","處新臺幣三萬元以上三百萬元以下罰鍰"],"a",
 "第41條：建築物污水處理設施違反第7條第1項（放流水標準）或第8條（污泥妥善處理）規定者，處新臺幣三千元以上三十萬元以下罰鍰。此額度為本法各罰鍰中最低者，遠低於第40條事業之六萬元以上二千萬元以下。",
 "What fine applies where a building sewage treatment facility breaches Article 7 or Article 8?",
 ["A fine of NT$3,000 to NT$300,000","A fine of NT$60,000 to NT$20,000,000","A fine of NT$6,000 to NT$600,000","A fine of NT$30,000 to NT$3,000,000"],
 "Article 41, the lowest fine range in the Act."),

(W,"第42條",2,"水污法-處罰對象",
 "污水下水道系統或建築物污水處理設施違反第七條第一項或第八條規定時，應處罰何人？",
 ["處罰其所有人、使用人或管理人；為共同所有或共同使用且無管理人者，應對共同所有人或共同使用人處罰","處罰其設計或施工之營造廠商；為共同所有或共同使用者，由該建築物之管理委員會主任委員個人負責","處罰當地下水道管理機關；為共同所有或共同使用者，由該地方主管機關編列預算代為繳納罰鍰即可","處罰該設施之原始起造人；為共同所有或共同使用且無管理人者，一律免罰而僅通知限期改善即可"],"a",
 "第42條：污水下水道系統或建築物污水處理設施違反第7條第1項或第8條規定者，處罰其所有人、使用人或管理人；為共同所有或共同使用且無管理人者，應對共同所有人或共同使用人處罰。第25條並定建築物污水處理設施應由所有人、使用人或管理人自行或委託清除機構清理。",
 "Who is penalised when a sewer system or building sewage facility breaches Article 7 or 8?",
 ["The owner, user or manager; where it is jointly owned or used with no manager, the joint owners or joint users are penalised","The design or construction contractor; where jointly owned or used, the chair of the building management committee is personally liable","The local sewerage authority; where jointly owned or used, the local competent authority budgets for and pays the fine on their behalf","The original developer of the facility; where jointly owned or used with no manager, no penalty applies and improvement is merely ordered"],
 "Article 42; see also Article 25."),

(W,"第43條",2,"水污法-違反總量管制",
 "事業或污水下水道系統違反依第九條第二項所定之總量管制方式者，如何處罰？",
 ["處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停工或停業","處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停工或停業","處新臺幣一萬元以上六十萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；情節重大者得令停止作為","處新臺幣六千元以上三十萬元以下罰鍰，並通知限期申報，屆期未申報者按次處罰；情節重大者得勒令歇業"],"a",
 "第43條：事業或污水下水道系統違反依第9條第2項所定之總量管制方式者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者按次處罰；情節重大者得令其停工或停業，必要時並得廢止其水污染防治許可證（文件）或勒令歇業。第73條並定情節重大之認定情形。",
 "What penalty applies to breaching the total load control scheme under Article 9, paragraph 2?",
 ["A fine of NT$30,000 to NT$3,000,000 with an improvement deadline and consecutive penalties; suspension of operations or business in serious cases","A fine of NT$60,000 to NT$20,000,000 with an improvement deadline and consecutive penalties; suspension of operations or business in serious cases","A fine of NT$10,000 to NT$600,000 with a correction deadline and consecutive penalties; an order to cease the act in serious cases","A fine of NT$6,000 to NT$300,000 with a reporting deadline and consecutive penalties; an order to close down the business in serious cases"],
 "Article 43; serious cases defined in Article 73."),

(W,"第44條",3,"水污法-費用未繳",
 "事業或污水下水道系統未於期限內繳納水污染防治費者，應如何處理？",
 ["應依繳納期限當日郵政儲金一年期定期存款固定利率按日加計利息一併繳納；逾期九十日仍未繳納者，處新臺幣六千元以上三十萬元以下罰鍰","應依繳納期限當日銀行基準放款利率按月加計滯納金一併繳納；逾期三十日仍未繳納者，處新臺幣一萬元以上一百萬元以下罰鍰並移送強制執行","應加計應繳費額百分之十五之滯納金一併繳納；逾期六十日仍未繳納者，處新臺幣三萬元以上三百萬元以下罰鍰並得令其停工或停業至繳清為止","應依繳納期限當日消費者物價指數年增率按日加計利息；逾期一百八十日仍未繳納者，處新臺幣六萬元以上六百萬元以下罰鍰並廢止其許可證"],"a",
 "第44條第1項：事業或污水下水道系統（不含公共污水下水道系統及社區專用污水下水道系統）違反第11條第8項所定辦法未於期限內繳納費用者，應依繳納期限當日郵政儲金一年期定期存款固定利率按日加計利息一併繳納；逾期九十日仍未繳納者，處新臺幣六千元以上三十萬元以下罰鍰。",
 "What happens if an enterprise fails to pay the water pollution control fee on time?",
 ["Interest accrues daily at the one year postal savings fixed deposit rate on the due date; if unpaid after ninety days, a fine of NT$6,000 to NT$300,000 applies","A monthly surcharge accrues at the bank prime lending rate on the due date; if unpaid after thirty days, a fine of NT$10,000 to NT$1,000,000 and compulsory enforcement","A surcharge of fifteen percent of the sum due is added; if unpaid after sixty days, a fine of NT$30,000 to NT$3,000,000 and suspension of operations until paid in full","Interest accrues daily at the consumer price index growth rate on the due date; if unpaid after one hundred and eighty days, a fine of NT$60,000 to NT$6,000,000 and permit revocation"],
 "Article 44, paragraph 1."),

(W,"第44條",2,"水污法-家戶罰則",
 "家戶未於期限內繳納水污染防治費且逾九十日仍未繳納者，如何處罰？其裁罰準則由何機關訂定？",
 ["地方政府應對該家戶處新臺幣一千五百元以上三萬元以下罰鍰；其裁罰準則由地方政府定之，不適用第六十六條之一規定","地方政府應對該家戶處新臺幣六千元以上三十萬元以下罰鍰；其裁罰準則由中央主管機關定之，並適用第六十六條之一規定","中央主管機關應對該家戶處新臺幣三千元以上三十萬元以下罰鍰；其裁罰準則由行政院定之，不適用第六十六條之一規定","地方政府應對該家戶處新臺幣一萬元以上十萬元以下罰鍰；其裁罰準則由該地方民意機關議決之，並適用第六十六條之一規定"],"a",
 "第44條第2項：家戶違反第11條第9項所定自治法規未於期限內繳納費用且逾九十日仍未繳納者，地方政府應對該家戶處新臺幣一千五百元以上三萬元以下罰鍰。第3項：處罰鍰額度應依違規情節裁處，其裁罰準則由地方政府定之，不適用第66條之1（中央訂定裁罰準則）之規定。",
 "How are households fined for non payment after ninety days, and who sets the criteria?",
 ["The local government fines them NT$1,500 to NT$30,000; the local government sets the criteria, and Article 66-1 does not apply","The local government fines them NT$6,000 to NT$300,000; the central authority sets the criteria, and Article 66-1 does apply","The central authority fines them NT$3,000 to NT$300,000; the Executive Yuan sets the criteria, and Article 66-1 does not apply","The local government fines them NT$10,000 to NT$100,000; the local council resolves the criteria, and Article 66-1 does apply"],
 "Article 44, paragraphs 2 and 3."),

(W,"第45條",3,"水污法-無照排放",
 "未取得排放許可證或簡易排放許可文件而排放廢（污）水者，如何處罰？",
 ["處新臺幣六萬元以上六百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時應勒令歇業","處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；必要時得停工","處新臺幣三萬元以上三百萬元以下罰鍰，主管機關並得令事業部分停工；必要時得廢止其許可文件","處新臺幣一萬元以上六十萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰並得停業"],"a",
 "第45條第1項：違反第14條第1項未取得排放許可證或簡易排放許可文件而排放廢（污）水者，處新臺幣六萬元以上六百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時，應勒令歇業。此處停工停業係「應」為而非「得」為，與第2項未依登記事項運作之處理不同。第36條第3項並定無許可證而排放有害健康物質者加重刑責。",
 "What penalty applies to discharging without a permit or simplified permit document?",
 ["A fine of NT$60,000 to NT$6,000,000, and the authority must order the enterprise to halt all operations or business; closure where necessary","A fine of NT$60,000 to NT$6,000,000, with a correction deadline and consecutive penalties if uncorrected; suspension where necessary","A fine of NT$30,000 to NT$3,000,000, and the authority may order the enterprise to halt part of operations; permit revocation where necessary","A fine of NT$10,000 to NT$600,000, with an improvement deadline and consecutive penalties if not improved, plus suspension of business"],
 "Article 45, paragraph 1; note the mandatory suspension."),

(W,"第45條",3,"水污法-未依登記運作",
 "違反第十四條第一項未依排放許可證登記事項運作者，與違反第十四條第二項者，罰鍰各為何？",
 ["未依登記事項運作者處新臺幣六萬元以上六百萬元以下罰鍰並通知限期補正；違反第十四條第二項者處新臺幣一萬元以上六十萬元以下罰鍰並通知限期補正","未依登記事項運作者處新臺幣三萬元以上三百萬元以下罰鍰並通知限期改善；違反第十四條第二項者處新臺幣六千元以上三十萬元以下罰鍰並通知限期申報","未依登記事項運作者處新臺幣一萬元以上六百萬元以下罰鍰並應令全部停工；違反第十四條第二項者處新臺幣三萬元以上三百萬元以下罰鍰並得令停業","未依登記事項運作者處新臺幣六萬元以上二千萬元以下罰鍰並勒令歇業；違反第十四條第二項者處新臺幣六萬元以上六百萬元以下罰鍰並得廢止許可"],"a",
 "第45條第2項：違反第14條第1項未依排放許可證或簡易排放許可文件之登記事項運作者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；情節重大者得令停工或停業。第3項：違反第14條第2項（未於規定期限辦理變更）者，處新臺幣一萬元以上六十萬元以下罰鍰，並通知限期補正。",
 "What fines apply for not operating as registered under Article 14 paragraph 1, and for breaching paragraph 2?",
 ["Not operating as registered brings NT$60,000 to NT$6,000,000 with a correction deadline; breaching paragraph 2 brings NT$10,000 to NT$600,000 with a correction deadline","Not operating as registered brings NT$30,000 to NT$3,000,000 with an improvement deadline; breaching paragraph 2 brings NT$6,000 to NT$300,000 with a reporting deadline","Not operating as registered brings NT$10,000 to NT$6,000,000 with mandatory full suspension; breaching paragraph 2 brings NT$30,000 to NT$3,000,000 with suspension","Not operating as registered brings NT$60,000 to NT$20,000,000 with forced closure; breaching paragraph 2 brings NT$60,000 to NT$6,000,000 with permit revocation"],
 "Article 45, paragraphs 2 and 3."),

(W,"第46條",2,"水污法-違反防治措施辦法",
 "違反依第十三條第四項或第十八條所定辦法規定者，如何處罰？",
 ["處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停工或停業","處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停止作為","處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得勒令歇業","處新臺幣六千元以上三百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停止貯存"],"a",
 "第46條：違反依第13條第4項（管線排放海洋）或第18條（水污染防治措施管理辦法）所定辦法規定者，處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰；情節重大者得令其停工或停業，必要時並得廢止許可證（文件）或勒令歇業。",
 "What penalty applies to breaching the regulations under Article 13 paragraph 4 or Article 18?",
 ["A fine of NT$10,000 to NT$6,000,000 with a correction or improvement deadline and consecutive penalties; suspension of operations or business in serious cases","A fine of NT$60,000 to NT$6,000,000 with a correction or improvement deadline and consecutive penalties; an order to cease the act in serious cases","A fine of NT$30,000 to NT$3,000,000 with a correction or improvement deadline and consecutive penalties; forced closure of the business in serious cases","A fine of NT$6,000 to NT$3,000,000 with a correction or improvement deadline and consecutive penalties; an order to cease storage in serious cases"],
 "Article 46."),

(W,"第46條之1",3,"水污法-繞流罰則",
 "排放廢（污）水違反第十八條之一第一項、第二項或第四項規定者，罰鍰額度為何？",
 ["處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停工或停業","處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停止作為","處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；情節重大者得廢止許可文件","處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得勒令歇業"],"a",
 "第46條之1：排放廢（污）水違反第18條之1第1項（繞流排放）、第2項（稀釋）或第4項（處理設施應具足夠功能設備並維持正常操作）規定者，處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停工或停業。違反第18條之1第1項另可能依第36條第3項加重刑責。",
 "What fine applies to breaching Article 18-1 paragraphs 1, 2 or 4?",
 ["A fine of NT$60,000 to NT$20,000,000 with an improvement deadline and consecutive penalties; suspension of operations or business in serious cases","A fine of NT$60,000 to NT$6,000,000 with an improvement deadline and consecutive penalties; an order to cease the act in serious cases","A fine of NT$10,000 to NT$6,000,000 with a correction deadline and consecutive penalties; revocation of the permit document in serious cases","A fine of NT$30,000 to NT$3,000,000 with an improvement deadline and consecutive penalties; forced closure of the business in serious cases"],
 "Article 46-1; see also Article 36, paragraph 3."),

(W,"第47條",2,"水污法-下水道系統罰則",
 "污水下水道系統違反第十九條準用規定者，如何處罰？",
 ["處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰","處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰","處新臺幣三千元以上三十萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰","處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰"],"a",
 "第47條：污水下水道系統違反第19條規定（準用第14條排放許可、第15條有效期間、第18條防治措施）者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰。",
 "What penalty applies to a sewer system breaching Article 19?",
 ["A fine of NT$60,000 to NT$6,000,000, with a correction or improvement deadline and consecutive penalties if it is not met","A fine of NT$60,000 to NT$20,000,000, with a correction or improvement deadline and consecutive penalties if it is not met","A fine of NT$3,000 to NT$300,000, with a correction or improvement deadline and consecutive penalties if it is not met","A fine of NT$10,000 to NT$100,000, with a correction or improvement deadline and consecutive penalties if it is not met"],
 "Article 47."),

(W,"第48條",3,"水污法-貯留稀釋罰則",
 "未取得貯留或稀釋許可文件而貯留或稀釋廢（污）水者，如何處罰？",
 ["處新臺幣三萬元以上三百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時應勒令歇業","處新臺幣六萬元以上六百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時應勒令歇業","處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期未完成改善者得令其部分停工","處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰並得廢止許可"],"a",
 "第48條第1項：事業或污水下水道系統違反第20條第1項未取得貯留或稀釋許可文件而貯留或稀釋廢（污）水者，處新臺幣三萬元以上三百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時，應勒令歇業。第2項未依貯留或稀釋許可文件登記事項運作者，罰鍰額度相同但改為通知限期補正並按次處罰。",
 "What penalty applies to storing or diluting wastewater without the permit document?",
 ["A fine of NT$30,000 to NT$3,000,000, and the authority must order the enterprise to halt all operations or business; closure where necessary","A fine of NT$60,000 to NT$6,000,000, and the authority must order the enterprise to halt all operations or business; closure where necessary","A fine of NT$30,000 to NT$3,000,000, with an improvement deadline and partial suspension of operations if it is not met in time","A fine of NT$10,000 to NT$100,000, with a correction deadline, consecutive penalties if uncorrected and possible permit revocation"],
 "Article 48, paragraphs 1 and 2."),

(W,"第48條",2,"水污法-專責人員罰則",
 "事業違反專責單位或人員設置規定，及廢（污）水處理專責人員違反所定辦法者，各如何處罰？",
 ["事業處新臺幣一萬元以上十萬元以下罰鍰並通知限期補正或改善；專責人員亦處新臺幣一萬元以上十萬元以下罰鍰，必要時得廢止其合格證書","事業處新臺幣三萬元以上三百萬元以下罰鍰並通知限期補正或改善；專責人員處新臺幣六千元以上六萬元以下罰鍰，必要時得廢止其合格證書","事業處新臺幣六萬元以上六百萬元以下罰鍰並應令其全部停工；專責人員處新臺幣一萬元以上十萬元以下罰鍰，並一律撤銷其專責人員合格證書","事業處新臺幣六千元以上三十萬元以下罰鍰並通知限期申報；專責人員免予處罰，僅由主管機關令其參加回訓課程並記錄於證書之上"],"a",
 "第48條第3項：事業或污水下水道系統違反第21條第1項（未設置專責單位或人員）或依第21條第2項所定辦法者，處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰。第4項：廢（污）水處理專責人員違反依第21條第2項所定辦法者，處新臺幣一萬元以上十萬元以下罰鍰；必要時得廢止其廢水處理專責人員合格證書。",
 "How are enterprises and dedicated wastewater personnel penalised for breaching Article 21 rules?",
 ["The enterprise is fined NT$10,000 to NT$100,000 with a correction or improvement deadline; the personnel likewise NT$10,000 to NT$100,000, and the certificate may be revoked","The enterprise is fined NT$30,000 to NT$3,000,000 with a correction or improvement deadline; the personnel NT$6,000 to NT$60,000, and the certificate may be revoked","The enterprise is fined NT$60,000 to NT$6,000,000 and must halt all operations; the personnel NT$10,000 to NT$100,000, and the certificate is always revoked outright","The enterprise is fined NT$6,000 to NT$300,000 with a reporting deadline; the personnel are not fined at all and merely ordered to attend a refresher course"],
 "Article 48, paragraphs 3 and 4."),

(W,"第49條",2,"水污法-檢測機構罰則",
 "違反第二十三條第一項或依第二十三條第二項所定管理辦法者，如何處罰？",
 ["處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停業，必要時並得廢止其許可證","處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停工，必要時並得勒令歇業","處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰；情節重大者得令停止作為並廢止合格證書","處新臺幣六千元以上三百萬元以下罰鍰，並通知限期申報或改善，屆期未申報或完成改善者按次處罰；情節重大者得令停止貯存並註銷登記"],"a",
 "第49條：違反第23條第1項（檢驗測定應委託許可之檢驗測定機構辦理）或依第23條第2項所定管理辦法者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者得令其停業，必要時並得廢止其許可證或勒令歇業。第73條並列舉情節重大之認定情形。",
 "What penalty applies to breaching Article 23, paragraph 1 or its regulations?",
 ["A fine of NT$30,000 to NT$3,000,000 with a correction or improvement deadline and consecutive penalties; suspension of business in serious cases and possible licence revocation","A fine of NT$60,000 to NT$6,000,000 with a correction or improvement deadline and consecutive penalties; suspension of operations in serious cases and possible forced closure","A fine of NT$10,000 to NT$6,000,000 with a correction or improvement deadline and consecutive penalties; an order to cease the act in serious cases and certificate revocation","A fine of NT$6,000 to NT$3,000,000 with a reporting or improvement deadline and consecutive penalties; an order to cease storage in serious cases and cancellation of registration"],
 "Article 49; serious cases under Article 73."),

(W,"第50條",2,"水污法-拒絕查證",
 "規避、妨礙或拒絕主管機關依第二十六條第一項所為查證者，如何處罰？",
 ["處新臺幣三萬元以上三百萬元以下罰鍰，並得按次處罰及強制執行查證工作","處新臺幣六萬元以上六百萬元以下罰鍰，並得按次處罰但不得強制執行查證","處新臺幣一萬元以上十萬元以下罰鍰，並通知限期改善後始得再行查證工作","處新臺幣六千元以上三十萬元以下罰鍰，並移請司法機關聲請搜索票後查證"],"a",
 "第50條：規避、妨礙或拒絕第26條第1項之查證者，處新臺幣三萬元以上三百萬元以下罰鍰，並得按次處罰及強制執行查證工作。第26條第3項並明定對於查證不得規避、妨礙或拒絕，第4項規定檢查機關與人員對受檢之工商、軍事秘密應予保密。",
 "What penalty applies to evading, obstructing or refusing an Article 26 inspection?",
 ["A fine of NT$30,000 to NT$3,000,000, imposable consecutively, and the inspection may be carried out by compulsion","A fine of NT$60,000 to NT$6,000,000, imposable consecutively, but the inspection may never be compelled","A fine of NT$10,000 to NT$100,000, with an improvement deadline before inspection may be attempted again","A fine of NT$6,000 to NT$300,000, with the case referred to the judiciary for a search warrant before inspection"],
 "Article 50; see Article 26, paragraphs 3 and 4."),

(W,"第51條",3,"水污法-應變罰則",
 "違反第二十七條第一項、第四項規定者與違反第二十八條第一項規定者，罰鍰額度各為何？",
 ["違反第二十七條者處新臺幣六萬元以上六百萬元以下罰鍰；違反第二十八條第一項者處新臺幣一萬元以上六百萬元以下罰鍰並通知限期補正或改善","違反第二十七條者處新臺幣三萬元以上三百萬元以下罰鍰；違反第二十八條第一項者處新臺幣六千元以上三十萬元以下罰鍰並通知限期補正或改善","違反第二十七條者處新臺幣一萬元以上六十萬元以下罰鍰；違反第二十八條第一項者處新臺幣六萬元以上二千萬元以下罰鍰並通知限期補正或改善","違反第二十七條者處新臺幣六萬元以上二千萬元以下罰鍰；違反第二十八條第一項者處新臺幣三千元以上三十萬元以下罰鍰並通知限期補正或改善"],"a",
 "第51條第1項：違反第27條第1項（緊急應變並三小時內通知）、第4項（不遵行必要防治措施命令）者，處新臺幣六萬元以上六百萬元以下罰鍰；必要時並得廢止其水污染防治許可證（文件）或勒令歇業。第2項：違反第28條第1項者，處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期未補正或完成改善者按次處罰。另未立即採取緊急應變措施者依第34條負刑責。",
 "What fines apply for breaching Article 27 paragraphs 1 and 4, and Article 28 paragraph 1?",
 ["Breaching Article 27 brings NT$60,000 to NT$6,000,000; breaching Article 28 paragraph 1 brings NT$10,000 to NT$6,000,000 with a correction or improvement deadline","Breaching Article 27 brings NT$30,000 to NT$3,000,000; breaching Article 28 paragraph 1 brings NT$6,000 to NT$300,000 with a correction or improvement deadline","Breaching Article 27 brings NT$10,000 to NT$600,000; breaching Article 28 paragraph 1 brings NT$60,000 to NT$20,000,000 with a correction or improvement deadline","Breaching Article 27 brings NT$60,000 to NT$20,000,000; breaching Article 28 paragraph 1 brings NT$3,000 to NT$300,000 with a correction or improvement deadline"],
 "Article 51, paragraphs 1 and 2; criminal liability under Article 34."),

(W,"第52條",2,"水污法-管制區與監測罰則",
 "違反第三十條第一項各款禁止行為或第三十一條第一項自動監測規定者，如何處罰？",
 ["處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停止作為或停工、停業","處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停止貯存或停工、停業","處新臺幣一萬元以上六十萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；情節重大者得令停止作為但不得停工停業","處新臺幣六千元以上三十萬元以下罰鍰，並通知限期申報，屆期未申報者按次處罰；情節重大者得令停止作為或勒令其歇業"],"a",
 "第52條：違反第30條第1項各款情形之一（水污染管制區內禁止行為）或第31條第1項（總量管制水體應設置自動監測系統）規定者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者按次處罰；情節重大者得令其停止作為或停工、停業，必要時並得廢止許可證（文件）或勒令歇業。",
 "What penalty applies to breaching Article 30 prohibitions or the Article 31 monitoring duty?",
 ["A fine of NT$30,000 to NT$3,000,000 with an improvement deadline and consecutive penalties; an order to cease the act or suspend operations in serious cases","A fine of NT$60,000 to NT$6,000,000 with an improvement deadline and consecutive penalties; an order to cease storage or suspend operations in serious cases","A fine of NT$10,000 to NT$600,000 with a correction deadline and consecutive penalties; an order to cease the act but never suspension in serious cases","A fine of NT$6,000 to NT$300,000 with a reporting deadline and consecutive penalties; an order to cease the act or forced closure in serious cases"],
 "Article 52."),

(W,"第53條",3,"水污法-土壤地下水罰則",
 "違反第三十二條第一項將廢（污）水注入地下水體或未取得許可證而排放於土壤者，如何處罰？",
 ["處新臺幣六萬元以上六百萬元以下罰鍰；主管機關並應令事業全部停工或停業，必要時應勒令歇業","處新臺幣三萬元以上三百萬元以下罰鍰；主管機關並得令事業部分停工，必要時得廢止其許可證","處新臺幣六萬元以上二千萬元以下罰鍰；主管機關並應通知限期改善，屆期未改善者始得令停工","處新臺幣一萬元以上六百萬元以下罰鍰；主管機關並得令停止貯存，必要時得移送司法機關偵辦"],"a",
 "第53條第1項：違反第32條第1項將廢（污）水注入地下水體或未取得排放土壤處理許可證而排放廢（污）水於土壤者，處新臺幣六萬元以上六百萬元以下罰鍰；主管機關並應令事業全部停工或停業；必要時應勒令歇業。第2項未依土壤處理許可證登記事項運作者罰鍰相同，但改為通知限期補正並按次處罰。注入地下水體含有害健康物質者另依第36條第2項處一年以上七年以下有期徒刑。",
 "What penalty applies to injecting wastewater into groundwater or discharging to soil without a permit?",
 ["A fine of NT$60,000 to NT$6,000,000; the authority must order the enterprise to halt all operations or business, with closure where necessary","A fine of NT$30,000 to NT$3,000,000; the authority may order partial suspension of operations, with permit revocation where necessary","A fine of NT$60,000 to NT$20,000,000; the authority must first set an improvement deadline and may only then order suspension of operations","A fine of NT$10,000 to NT$6,000,000; the authority may order storage to cease and may refer the case to the judiciary where necessary"],
 "Article 53; see also Article 36, paragraph 2."),

(W,"第54條",2,"水污法-貯存物質罰則",
 "違反第三十三條第一項、第二項貯存指定物質相關規定者，如何處罰？",
 ["處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停止貯存或停工、停業","處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；情節重大者得令停止作為或停工、停業","處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正，屆期未補正者按次處罰；情節重大者得令全部停工並勒令其歇業","處新臺幣六千元以上三百萬元以下罰鍰，並通知限期申報，屆期未申報者按次處罰；情節重大者得令停止貯存並廢止許可證"],"a",
 "第54條：違反第33條第1項（貯存公告指定物質應設置防止污染地下水體設施及監測設備並經備查）、第2項（監測設備應監測、記錄及申報）規定者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者按次處罰；情節重大者得令其停止貯存或停工、停業，必要時並得勒令歇業。",
 "What penalty applies to breaching Article 33, paragraphs 1 or 2 on storing designated substances?",
 ["A fine of NT$60,000 to NT$6,000,000 with an improvement deadline and consecutive penalties; an order to cease storage or suspend operations in serious cases","A fine of NT$30,000 to NT$3,000,000 with an improvement deadline and consecutive penalties; an order to cease the act or suspend operations in serious cases","A fine of NT$10,000 to NT$6,000,000 with a correction deadline and consecutive penalties; an order to halt all operations and forced closure in serious cases","A fine of NT$6,000 to NT$3,000,000 with a reporting deadline and consecutive penalties; an order to cease storage and permit revocation in serious cases"],
 "Article 54."),

(W,"第55條",2,"水污法-情節重大處分",
 "違反本法規定經認定情節重大者，主管機關得如何處理？",
 ["得依本法規定逕命停止作為、停止貯存、停工或停業；必要時並勒令歇業","應先通知限期改善屆滿後，始得命停工或停業，並不得逕命停止作為","僅得加重罰鍰額度至法定最高額，不得命停工、停業或勒令其歇業","應報請中央主管機關核准後，始得命停止作為或停工，不得勒令歇業"],"a",
 "第55條：違反本法規定，經認定情節重大者，主管機關得依本法規定逕命停止作為、停止貯存、停工或停業；必要時，並勒令歇業。第73條第1項列舉情節重大之七款認定情形，第2項並定應公開該事業並停止追回其優惠待遇。",
 "What may the authority do where a breach is found to be serious?",
 ["Order directly under this Act to cease the act, cease storage, or suspend operations or business; and close the business where necessary","Set an improvement deadline first and only then order suspension of operations or business, never ordering the act to cease directly","Only raise the fine to the statutory maximum, without power to order suspension of operations or business or forced closure","Seek central authority approval before ordering the act to cease or operations to stop, with forced closure never available"],
 "Article 55; serious cases listed in Article 73."),

(W,"第56條",2,"水污法-未申報罰則",
 "依第二十條第三項、第二十二條、第三十一條第二項、第三十二條第四項或第三十三條第二項有申報義務而不為申報者，如何處罰？",
 ["處新臺幣六千元以上三百萬元以下罰鍰，並通知限期申報，屆期未申報或申報不完全者按次處罰","處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期申報，屆期未申報或申報不完全者按次處罰","處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上三百萬元以下罰金並得按次處罰","處新臺幣一萬元以上十萬元以下罰鍰，並廢止其許可證，補行申報後始得重新申請核發許可"],"a",
 "第56條：依第20條第3項、第22條、第31條第2項、第32條第4項或第33條第2項有申報義務，不為申報者，處新臺幣六千元以上三百萬元以下罰鍰，並通知限期申報，屆期未申報或申報不完全者，按次處罰。此為行政罰；若係明知不實而申報不實，則另依第35條負三年以下有期徒刑之刑事責任。",
 "What penalty applies to failing to file reports required by Articles 20, 22, 31, 32 or 33?",
 ["A fine of NT$6,000 to NT$3,000,000, with a reporting deadline and consecutive penalties if still unreported or incomplete","A fine of NT$30,000 to NT$3,000,000, with a reporting deadline and consecutive penalties if still unreported or incomplete","Up to three years imprisonment, detention or a fine of NT$200,000 to NT$3,000,000, imposable consecutively for each breach","A fine of NT$10,000 to NT$100,000 with revocation of the permit, reapplication being allowed only after reporting"],
 "Article 56; contrast the criminal liability in Article 35."),

(W,"第57條",1,"水污法-改善期限準則",
 "本法所定屆期未補正或完成改善之按次處罰，其限期改善期限及查驗方式等事項之準則由何機關訂定？",
 ["由中央主管機關定之","由地方主管機關定之","由目的事業機關定之","由行政院會商後定之"],"a",
 "第57條：本法所定屆期仍未補正或完成改善之按次處罰，其限期改善或補正之期限、改善完成認定查驗方式、法令執行方式及其他應遵行事項之準則，由中央主管機關定之。第61條並定補正、改善或申報期間不得超過九十日。",
 "Who issues the criteria for improvement deadlines and verification methods for consecutive penalties?",
 ["The central competent authority","The local competent authority","The industry competent authority","The Executive Yuan after consultation"],
 "Article 57; see Article 61 on the ninety day cap."),

(W,"第57條之1",3,"水污法-改善期間惡化",
 "事業及污水下水道系統於改善期間，何種情形應按次處罰？",
 ["排放之廢（污）水污染物項目超過原據以處罰之排放濃度，或氫離子濃度指數更形惡化者","改善期間仍繼續生產或營業，且未向主管機關申報改善進度及各項工程施作情形者","改善期間未設置廢水處理專責人員常駐現場監督，或未每日記錄處理設施操作情形者","改善期間排放水量超過許可核准量之百分之八十，或未於期滿前十五日提出改善報告"],"a",
 "第57條之1：事業及污水下水道系統於改善期間，排放之廢（污）水污染物項目超過原據以處罰之排放濃度或氫離子濃度指數更形惡化者，應按次處罰。此係改善期間之特別規定，與第60條（未於改善期限屆滿前檢具證明文件送交主管機關者視為未完成改善）併同適用。",
 "During the improvement period, what triggers consecutive penalties?",
 ["Discharging a pollutant item above the concentration originally penalised, or a further deterioration of the pH value of the effluent","Continuing production or business during the improvement period without reporting progress and construction work to the authority","Failing to keep dedicated wastewater personnel stationed on site during improvement, or failing to log facility operation daily","Discharging more than eighty percent of the permitted volume, or not submitting an improvement report fifteen days before expiry"],
 "Article 57-1; see also Article 60."),

(W,"第58條",2,"水污法-分別處罰",
 "同一事業設置數放流口，或數事業共同設置廢水處理設施或使用同一放流口，其排放未符標準時如何處罰？",
 ["應分別處罰","應合併處罰","應減半處罰","應擇一處罰"],"a",
 "第58條：同一事業設置數放流口，或數事業共同設置廢水處理設施或使用同一放流口，其排放廢水未符合放流水標準或本法其他規定者，應分別處罰。此規定避免共用設施而規避處罰，與第42條（共同所有或共同使用且無管理人者應對共同所有人或使用人處罰）意旨相近。",
 "How are breaches penalised where one enterprise has several outlets or several enterprises share one outlet?",
 ["They are penalised separately","They are penalised as one","The penalty is halved","Only one of them is penalised"],
 "Article 58; compare Article 42."),

(W,"第59條",3,"水污法-設施故障",
 "廢（污）水處理設施發生故障時，於故障發生幾小時內符合規定者得不適用主管機關所定標準？其中恢復正常操作之要求為何？",
 ["於故障發生二十四小時內；並應於故障發生二十四小時內恢復正常操作，或於恢復正常操作前減少、停止生產及服務作業","於故障發生四十八小時內；並應於故障發生四十八小時內恢復正常操作，或於恢復正常操作前減少、停止生產及服務作業","於故障發生三小時內；並應於故障發生十二小時內恢復正常操作，或於恢復正常操作前減少、停止生產及服務作業","於故障發生七十二小時內；並應於故障發生五日內恢復正常操作，或於恢復正常操作前減少、停止生產及服務作業"],"a",
 "第59條第1項：廢（污）水處理設施發生故障，符合各款規定者，於故障發生二十四小時內得不適用主管機關所定標準；第3款要求於故障發生二十四小時內恢復正常操作，或於恢復正常操作前減少、停止生產及服務作業。另第1款應立即修復或啟用備份裝置並採應變措施，第2款應立即記錄並向當地主管機關報備。",
 "Within how many hours of a treatment facility breakdown may standards be disapplied, and what restoration is required?",
 ["Within twenty four hours of the breakdown; normal operation must resume within twenty four hours, or production and services be reduced or stopped until it does","Within forty eight hours of the breakdown; normal operation must resume within forty eight hours, or production and services be reduced or stopped until it does","Within three hours of the breakdown; normal operation must resume within twelve hours, or production and services be reduced or stopped until it does","Within seventy two hours of the breakdown; normal operation must resume within five days, or production and services be reduced or stopped until it does"],
 "Article 59, paragraph 1, subparagraph 3."),

(W,"第59條",3,"水污法-故障報備要件",
 "廢（污）水處理設施故障欲適用免責規定，除立即修復及恢復操作外，尚應符合哪些要件？",
 ["應立即記錄故障設施名稱及時間並向當地主管機關以電話或電傳報備、於五日內提出書面報告、故障與所違反標準有直接關係、不屬六個月內相同之故障","應於故障後三日內記錄並向中央主管機關以書面報備、於十五日內提出改善計畫、故障與所違反標準有間接關係即可、不屬一年內相同之故障","應於次月申報時一併載明故障設施名稱及時間、於三十日內提出書面報告、故障與所違反標準有直接關係、不屬三個月內相同之故障即可","應立即通知目的事業主管機關並副知檢驗測定機構、於七日內提出書面報告、故障原因不可歸責於事業、不屬二年內相同之故障"],"a",
 "第59條第1項第2款至第6款：應立即於故障紀錄簿記錄故障設施名稱及故障時間，並向當地主管機關以電話或電傳報備並記錄發話人、受話人姓名職稱；於五日內向當地主管機關提出書面報告；故障與所違反之該項放流水標準有直接關係；不屬六個月內相同之故障。第2項並列舉書面報告應包括設施名稱及故障時間、發生原因及修復方法等六項內容。",
 "Besides immediate repair and restoration, what conditions must a breakdown meet for the exemption?",
 ["Immediate logging of the facility and time with phone or fax notice to the local authority, a written report within five days, a direct link to the breached standard, and no same breakdown within six months","Logging within three days with written notice to the central authority, an improvement plan within fifteen days, an indirect link to the breached effluent standard, and no identical breakdown within one year","Noting the facility and time in the following month's report, a written report within thirty days, a direct link to the breached standard, and no same breakdown within three months","Immediate notice to the industry authority copied to the testing organisation, a written report within seven days, no fault on the enterprise, and no same breakdown within two years"],
 "Article 59, paragraph 1, subparagraphs 2 to 6, and paragraph 2."),

(W,"第60條",2,"水污法-視為未完成改善",
 "事業未於依第四十條、第四十三條、第四十六條或第五十三條所為通知改善之期限屆滿前，未檢具符合標準之證明文件送交主管機關者，效果為何？",
 ["視為未完成改善","視為已完成改善","得申請延長改善期限","僅通知補正不生效果"],"a",
 "第60條：事業未於依第40條、第43條、第46條或第53條所為通知改善之期限屆滿前，檢具符合主管機關所定標準或其他規定之證明文件，送交主管機關收受者，視為未完成改善。既視為未完成改善，即依各該條按次處罰；第62條另定因天災或不可抗力不能於期限內完成改善之處理方式。",
 "What is the effect of not submitting proof of compliance before the improvement deadline expires?",
 ["It is deemed that improvement has not been completed","It is deemed that improvement has been completed","An extension of the improvement period may be sought","Only a correction notice issues, with no legal effect"],
 "Article 60; see Article 62 for force majeure."),

(W,"第61條",1,"水污法-期間上限",
 "依本法通知限期補正、改善或申報者，其補正、改善或申報期間之上限為何？",
 ["不得超過九十日","不得超過三十日","不得超過一百八十日","不得超過三百六十五日"],"a",
 "第61條：依本法通知限期補正、改善或申報者，其補正、改善或申報期間，不得超過九十日。第57條並定限期改善或補正之期限、改善完成認定查驗方式等準則由中央主管機關定之；第62條則定因天災或不可抗力得申請核定賸餘期間之起算日。",
 "What is the maximum period allowed for ordered correction, improvement or reporting?",
 ["It may not exceed ninety days","It may not exceed thirty days","It may not exceed one hundred and eighty days","It may not exceed three hundred and sixty five days"],
 "Article 61."),

(W,"第62條",2,"水污法-不可抗力",
 "因天災或其他不可抗力事由致不能於改善期限內完成改善者，應如何辦理？",
 ["應於原因消滅後繼續進行改善，並於十五日內以書面敘明理由檢具證明文件，向當地主管機關申請核定賸餘期間之起算日","應於原因消滅後三十日內以書面敘明理由，向中央主管機關申請免除本次處罰，經核准者該次違規不予處分亦不列入紀錄","應於天災發生後立即停工並報請主管機關備查，改善期限自動順延三個月，無須另行申請核定賸餘期間之起算日期","應於原因消滅後六十日內檢具證明文件向目的事業主管機關申請延長，延長期間併計原期間不得超過一百八十日為限"],"a",
 "第62條：事業、污水下水道系統或建築物污水處理設施，因天災或其他不可抗力事由致不能於改善期限內完成改善者，應於其原因消滅後繼續進行改善，並於十五日內以書面敘明理由，檢具有關證明文件，向當地主管機關申請核定賸餘期間之起算日。與第61條九十日期間上限併同適用。",
 "What must be done where force majeure prevents completing improvement within the deadline?",
 ["Continue improvement once the cause ends and, within fifteen days, apply in writing with supporting documents to the local authority to fix the start of the remaining period","Apply in writing to the central authority within thirty days after the cause ends for exemption, the breach then drawing no penalty and no record","Halt operations immediately and file with the authority, the improvement deadline then being automatically extended by three months without any application","Apply to the industry competent authority within sixty days after the cause ends, the extension plus the original period not exceeding one hundred and eighty days"],
 "Article 62; read with Article 61."),

(W,"第63條",3,"水污法-試車復工",
 "事業經停業或停工者，復工（業）前應辦理何程序？試車期限為何？",
 ["應於復工（業）前檢具水污染防治措施及污泥處理改善計畫申請試車，經審查通過始得依計畫試車；試車期限不得超過三個月，且應於期限屆滿前申請復工（業）","應於復工（業）前檢具環境影響評估差異分析報告申請試車，經審查通過始得依計畫試車；試車期限不得超過六個月，且應於期限屆滿後申請復工（業）","應於復工（業）後三十日內補送水污染防治措施改善計畫備查即可；試車期限不得超過一年，並得於試車期間逕行恢復全部產能之正常生產作業","應於復工（業）前取得目的事業主管機關同意函並報中央主管機關備查；試車期限不得超過三個月，試車期間所排放之廢水不受放流水標準拘束"],"a",
 "第63條第1項、第2項：事業經停業、部分或全部停工者，應於復工（業）前檢具水污染防治措施及污泥處理改善計畫申請試車，經審查通過始得依計畫試車；經主管機關命限期改善而自報停工（業）者亦同。試車期限不得超過三個月，且應於試車期限屆滿前申請復工（業）；審查期間經同意者，在申報可處理至符合標準之廢（污）水產生量下得繼續操作。",
 "What must an enterprise do before resuming operations after suspension, and how long may test runs last?",
 ["Apply for a test run with a control measure and sludge improvement plan before resuming, running only after approval; test runs may not exceed three months and resumption must be sought before they end","Apply for a test run with an EIA difference analysis report before resuming, running only after approval; test runs may not exceed six months and resumption is sought after they end","Merely file an improvement plan for recordation within thirty days after resuming; test runs may not exceed one year and full production may resume during the test period","Obtain an industry authority consent letter and file it with the central authority before resuming; test runs may not exceed three months and effluent standards do not bind any discharge during them"],
 "Article 63, paragraphs 1 and 2."),

(W,"第63條",3,"水污法-復工查驗",
 "事業申請復工（業）時，主管機關應於多久期間內完成幾日以上之查驗及評鑑？經查驗不合格者如何處理？",
 ["應於一個月期間內經十五日以上之查驗及評鑑；經查驗評鑑不合格未經核准復工者應停止操作並進行改善，且一個月內不得再申請試車","應於三個月期間內經三十日以上之查驗及評鑑；經查驗評鑑不合格未經核准復工者應停止操作並進行改善，且三個月內不得再申請試車","應於十五日期間內經七日以上之查驗及評鑑；經查驗評鑑不合格未經核准復工者得繼續操作至改善完成，並隨時再行申請試車","應於六個月期間內經六十日以上之查驗及評鑑；經查驗評鑑不合格未經核准復工者應停止操作並進行改善，且一年內不得再申請試車"],"a",
 "第63條第3項：復工（業）之申請，主管機關應於一個月期間內，經十五日以上之查驗及評鑑，始得按其查驗及評鑑結果均符合管制標準時之廢（污）水產生量，作為核准復工（業）之製程操作條件，事業並應辦理排放許可登記事項之變更登記。第4項：經查驗及評鑑不合格未經核准復工者，應停止操作並進行改善，且一個月內不得再申請試車。第5項並定試車或復工期間違反本法者按次處罰或命停止操作。",
 "Within what period and for how long must verification be conducted, and what if it fails?",
 ["Within one month, with verification and evaluation of at least fifteen days; if it fails and resumption is refused, operations stop for improvement and no test run may be sought for one month","Within three months, with verification and evaluation of at least thirty days; if it fails and resumption is refused, operations stop for improvement and no test run may be sought for three months","Within fifteen days, with verification and evaluation of at least seven days; if it fails and resumption is refused, operations may continue until improvement and a test run be sought at any time","Within six months, with verification and evaluation of at least sixty days; if it fails and resumption is refused, operations stop for improvement and no test run may be sought for one year"],
 "Article 63, paragraphs 3 to 5."),

(W,"第63條之1",2,"水污法-計畫公開",
 "事業依第六十三條第一項提出之水污染防治措施及污泥處理改善計畫，應如何公開？審查程序有何要求？",
 ["應登載於中央主管機關所指定之公開網頁供民眾查詢；審查時應給予利害關係人及公益團體於完成審查前表示意見，會後應作成會議紀錄並公開登載","應於事業廠區大門及當地村里辦公處公告三十日；審查時應舉行公聽會並經出席之利害關係人過半數同意，會後應將紀錄函送與會人員存查","應刊登於全國性報紙及政府公報各一日；審查時得斟酌是否徵詢利害關係人意見，會議紀錄屬內部文件不對外公開以維護事業之營業秘密","應送當地鄉鎮市公所及民意機關備查；審查時應邀請公益團體列席但不得表示意見，會議紀錄應於審查結論確定後始得依申請提供閱覽"],"a",
 "第63條之1第1項：事業應將依第63條第1項所提出之水污染防治措施及污泥處理改善計畫，登載於中央主管機關所指定之公開網頁供民眾查詢。第2項：主管機關審查時應給予利害關係人及公益團體於完成審查前表示意見作為參考；會後應作成會議紀錄並公開登載於前項網頁。第69條另定應公開許可證（文件）及申報資料。",
 "How must the improvement plan under Article 63 be made public, and what does review require?",
 ["Posted on the public webpage designated by the central authority; interested parties and public interest groups may comment before review ends, and minutes are made and posted","Posted at the plant gate and village office for thirty days; a public hearing is held needing majority consent of attendees, with minutes sent to participants","Published once each in a national newspaper and the gazette; consulting interested parties is discretionary and minutes stay internal to protect trade secrets","Filed with the township office and the local council for recordation; public interest groups may attend but not comment, and minutes are released on request only after the conclusion is settled"],
 "Article 63-1; see also Article 69."),

(W,"第64條",1,"水污法-處罰機關",
 "本法所定之處罰，除另有規定外，由何機關為之？",
 ["在中央由行政院環境保護署為之，在直轄市由直轄市政府為之，在縣（市）由縣（市）政府為之","在中央由行政院為之，在直轄市由直轄市環保局為之，在縣（市）由縣（市）環保局為之","一律由中央主管機關為之，地方主管機關僅負責稽查取締及移送，不得自行裁處罰鍰","在中央由目的事業主管機關為之，在地方由該管鄉鎮市公所為之並由地方政府核定"],"a",
 "第64條：本法所定之處罰，除另有規定外，在中央由行政院環境保護署為之，在直轄市由直轄市政府為之，在縣（市）由縣（市）政府為之。此與第3條主管機關之分級一致。第66條並定停工停業、撤銷廢止許可證之執行由主管機關為之，勒令歇業則轉請目的事業主管機關為之。",
 "Which bodies impose the penalties under this Act, unless otherwise provided?",
 ["The Environmental Protection Administration centrally, the municipal government in municipalities, and the county or city government locally","The Executive Yuan centrally, the municipal environmental protection bureau, and the county or city environmental protection bureau locally","Always the central competent authority, local authorities merely inspecting and referring cases without power to impose fines","The industry competent authority centrally, and the township office locally with the county government approving each case"],
 "Article 64; consistent with Article 3."),

(W,"第65條",1,"水污法-條文刪除",
 "水污染防治法第六十五條之現行狀態為何？",
 ["該條業經刪除，現行條文僅保留條次而無實質內容規定","該條規定罰鍰之分期繳納方式及逾期加計利息之計算","該條規定主管機關得公布違規事業名單及違規內容","該條規定檢舉違反本法行為之獎金核發標準與程序"],"a",
 "第65條：（刪除）。本法另有第38條亦為刪除條文。與檢舉獎金相關者為第66條之4，規定民眾得檢舉違反本法之行為，主管機關對檢舉人身分應予保密，並得以實收罰鍰總金額收入之一定比例提充獎金獎勵檢舉人。",
 "What is the current status of Article 65 of the Water Pollution Control Act?",
 ["The article has been deleted, and only the article number remains without any substantive content","The article prescribes instalment payment of fines and the calculation of late payment interest","The article allows the authority to publish the names of violators and details of the breaches","The article sets the standards and procedure for paying rewards to those who report breaches"],
 "Article 65 (deleted); rewards are governed by Article 66-4."),

(W,"第66條",2,"水污法-執行機關",
 "本法之停工或停業、撤銷或廢止許可證之執行，與勒令歇業之執行，各由何機關為之？",
 ["停工停業、撤銷廢止許可證由主管機關為之；勒令歇業由主管機關轉請目的事業主管機關為之","停工停業、撤銷廢止許可證由目的事業主管機關為之；勒令歇業則由主管機關逕行執行之","二者均由主管機關逕行執行，無須轉請任何其他機關辦理，以免影響行政處分之效力","二者均由目的事業主管機關執行，主管機關僅負責作成處分書並送達受處分之事業"],"a",
 "第66條：本法之停工或停業、撤銷、廢止許可證之執行，由主管機關為之；勒令歇業，由主管機關轉請目的事業主管機關為之。此係因歇業涉及事業登記事項，須由主管其登記之目的事業主管機關辦理。第55條並定情節重大者得逕命停止作為、停止貯存、停工或停業。",
 "Who executes suspension or permit revocation, and who executes forced closure?",
 ["The competent authority executes suspension and permit revocation; forced closure is referred by it to the industry competent authority","The industry competent authority executes suspension and permit revocation; forced closure is executed directly by the competent authority","Both are executed directly by the competent authority without referral to any other body, so as not to weaken the disposition","Both are executed by the industry competent authority, the competent authority only issuing and serving the written disposition"],
 "Article 66; see also Article 55."),

(W,"第66條之1",1,"水污法-裁罰準則",
 "依本法處罰鍰者，其額度應如何裁處？裁罰準則由何機關訂定？",
 ["額度應依污染特性及違規情節裁處；裁罰準則由中央主管機關定之","額度應依事業之資本額及員工人數裁處；裁罰準則由行政院定之","額度應一律按法定最高額裁處；裁罰準則由地方主管機關分別定之","額度應依違規次數平均分配裁處；裁罰準則由目的事業主管機關定之"],"a",
 "第66條之1：依本法處罰鍰者，其額度應依污染特性及違規情節裁處；其裁罰準則由中央主管機關定之。惟第44條第3項就家戶未繳水污染防治費之罰鍰特別規定其裁罰準則由地方政府定之，不適用本條規定。",
 "How are fines under this Act set, and who issues the criteria?",
 ["By the pollution characteristics and the circumstances of the breach; the central competent authority issues the criteria","By the capital and number of employees of the enterprise; the Executive Yuan issues the criteria for such cases","Always at the statutory maximum amount; each municipal and county authority issues its own criteria separately","By dividing the total evenly across the number of breaches; the industry competent authority issues the criteria"],
 "Article 66-1; exception in Article 44, paragraph 3."),

(W,"第66條之2",3,"水污法-追繳利益",
 "違反本法義務行為而有所得利益者，除罰鍰外主管機關得如何處理？所稱利益包括哪些？",
 ["得於所得利益之範圍內予以追繳；所稱利益包括積極利益及應支出而未支出或減少支出之消極利益，其核算及推估辦法由中央主管機關定之","得於所得利益二倍之範圍內予以追繳；所稱利益僅限於實際取得之營業收入，不包括應支出而未支出之費用，核算方式由地方主管機關定之","得沒入其全部生產設備及產品；所稱利益包括積極利益及消極利益，其核算及推估辦法由行政院會商目的事業主管機關共同訂定後公告之","僅得加重罰鍰而不得另為追繳；所稱利益指違規期間之稅前純益，其核算應委由會計師查核簽證後報請中央主管機關核定並公告之"],"a",
 "第66條之2第1項：違反本法義務行為而有所得利益者，除依本法規定裁處罰鍰外，並得於所得利益之範圍內予以追繳。第2項、第3項並就為他人利益實施行為及他人因該行為受有財產上利益之情形定追繳規定。第4項：追繳由為裁處之主管機關以行政處分為之；所稱利益得包括積極利益及應支出而未支出或減少支出之消極利益，核算及推估辦法由中央主管機關定之。",
 "Besides fines, what may the authority do about gains from a breach, and what counts as gains?",
 ["Recover them within the amount of the gain; gains cover positive gains and negative gains from expenses avoided or reduced, with rules set by the central authority","Recover up to twice the gain; gains cover only revenue actually received and not expenses avoided, with the calculation rules set by the local authority","Confiscate all production equipment and products; gains cover positive and negative gains, with rules set jointly by the Executive Yuan and industry authorities","Only raise the fine without any recovery; gains mean pre tax net profit during the breach, certified by an accountant and approved centrally"],
 "Article 66-2, paragraphs 1 and 4."),

(W,"第66條之3",2,"水污法-特種基金",
 "各級主管機關依第十一條第六項設置之特種基金，其來源除水污染防治費外尚應包括什麼？該部分應優先支用於何處？",
 ["應包括依第六十六條之二追繳之所得利益及依本法裁處之部分罰鍰；該部分應優先支用於該違反本法義務者所污染水體之整治","應包括中央政府公務預算之補助款及民間捐贈款項；該部分應優先支用於水質監測站之設置及檢驗測定機構之許可查核作業","應包括各目的事業主管機關編列之輔導經費及規費收入；該部分應優先支用於水污染防治技術之研究發展與人員之訓練工作","應包括依本法裁處之全部罰鍰及沒入物之變賣價款；該部分應優先支用於公共污水下水道系統主次要幹管之新建與維護工程"],"a",
 "第66條之3第1項：各級主管機關依第11條第6項設置之特種基金，其來源除水污染防治費外，應包括依第66條之2追繳之所得利益及依本法裁處之部分罰鍰。第2項：屬追繳所得利益及裁處罰鍰者，應優先支用於該違反本法義務者所污染水體之整治。",
 "Besides the fee, what funds the special fund, and what must that part be spent on first?",
 ["Gains recovered under Article 66-2 and part of the fines imposed under this Act; that part must first be spent remediating the water body the violator polluted","Central government budget subsidies and private donations; that part must first be spent on monitoring stations and licensing audits of testing organisations","Guidance budgets of industry authorities and fee income; that part must first be spent on research and development of control technology and personnel training","All fines imposed under this Act and proceeds from confiscated items; that part must first be spent building and maintaining public sewer trunk mains"],
 "Article 66-3, paragraphs 1 and 2."),

(W,"第66條之4",2,"水污法-檢舉獎勵",
 "民眾檢舉違反本法之行為應向何機關為之？檢舉人之保護及獎勵如何規定？",
 ["得敘明事實或檢具證據向直轄市、縣（市）主管機關檢舉；主管機關對檢舉人身分應予保密，查證屬實並處罰鍰達一定數額者得以實收罰鍰之一定比例提充獎金","應具名並檢附證據向中央主管機關檢舉；主管機關對檢舉人身分得視情形決定是否保密，查證屬實者一律發給罰鍰金額百分之三十之檢舉獎金","得以匿名方式向目的事業主管機關檢舉；主管機關對檢舉人身分應予保密，惟查證屬實者不發給獎金以避免衍生職業檢舉之流弊情形","應向當地鄉鎮市公所提出書面檢舉；公所對檢舉人身分應予保密，並應於受理後十五日內轉送主管機關，獎金由公所編列預算支應"],"a",
 "第66條之4第1項：民眾得敘明事實或檢具證據資料，向直轄市、縣（市）主管機關檢舉違反本法之行為。第2項：主管機關對檢舉人身分應予保密；檢舉經查證屬實並處以罰鍰者，其罰鍰金額達一定數額時，得以實收罰鍰總金額收入之一定比例提充獎金獎勵檢舉人。第3項：檢舉及獎勵之資格、獎金提充比例、分配方式等辦法由直轄市、縣（市）主管機關定之。",
 "To whom are breaches reported, and how are informants protected and rewarded?",
 ["To the municipal or county authority with facts or evidence; the informant's identity is kept confidential, and a share of fines actually collected may fund a reward","To the central authority under one's own name with evidence; confidentiality is discretionary, and a reward of thirty percent of the fine is always paid on verification","Anonymously to the industry competent authority; the identity is kept confidential, but no reward is paid so as to discourage professional informants","In writing to the township office; it keeps the identity confidential, forwards the case within fifteen days, and funds any reward from its own budget"],
 "Article 66-4, paragraphs 1 to 3."),

(W,"第67條",1,"水污法-規費",
 "各級主管機關核發許可證、受理變更登記或各項申請之審查許可，應收取哪些規費？收費標準由何機關訂定？",
 ["應收取審查費、檢驗費或證書費等規費；其收費標準由中央主管機關會商有關機關定之","應收取審查費、檢驗費或證書費等規費；其收費標準由各級主管機關視實際成本分別定之","應收取許可費、保證金及環境維護費；其收費標準由目的事業主管機關會商中央定之","應收取審查費及污染防治保證金；其收費標準由行政院主計總處會商中央主管機關定之"],"a",
 "第67條：各級主管機關依本法核發許可證、受理變更登記或各項申請之審查、許可，應收取審查費、檢驗費或證書費等規費；其收費標準由中央主管機關會商有關機關定之。第23條第2項另定檢驗測定機構管理辦法及收費標準亦由中央主管機關定之。",
 "Which fees are charged for permits and applications, and who sets the fee schedule?",
 ["Review fees, testing fees and certificate fees; the central authority sets the schedule in consultation with the agencies concerned","Review fees, testing fees and certificate fees; each level of competent authority sets its own schedule based on actual costs","Permit fees, deposits and environmental maintenance fees; industry authorities set the schedule with the central authority","Review fees and pollution control deposits; the Directorate General of Budget sets the schedule with the central authority"],
 "Article 67; see also Article 23, paragraph 2."),

(W,"第68條",1,"水污法-檢測方法",
 "本法所定各項檢測之方法及品質管制事項，由何機關辦理？",
 ["由中央主管機關指定公告之","由各級主管機關分別指定公告之","由檢驗測定機構依國際標準自訂","由目的事業主管機關會商公會定之"],"a",
 "第68條：本法所定各項檢測之方法及品質管制事項，由中央主管機關指定公告之。第23條第1項並定水污染物及水質水量之檢驗測定，除經中央主管機關核准外，應委託中央主管機關核發許可證之檢驗測定機構辦理。",
 "Who prescribes the testing methods and quality control matters under this Act?",
 ["The central competent authority designates and announces them","Each level of competent authority designates and announces them","Testing organisations set their own by international standards","Industry authorities set them together with trade associations"],
 "Article 68; see also Article 23, paragraph 1."),

(W,"第69條",2,"水污法-資訊公開",
 "事業、污水下水道系統應將哪些資料公開於中央主管機關指定之網站？",
 ["主管機關核准之水污染防治許可證（文件）、依本法申報之資料，與環境工程技師、廢水處理專責人員及環境檢驗測定機構之證號資料","公司登記證明文件、最近三年財務報表、股東名冊、原物料採購清單，與廢水處理專責人員及環境檢驗測定機構之證號資料","廠區配置圖與製程流程圖、每日用水及用電紀錄、員工名冊、產品出貨數量，與環境工程技師簽證之全部計畫書及圖說內容","歷年遭裁處之罰鍰金額與繳納證明、訴願及行政訴訟結果、污染整治費用支出明細，與主管機關歷次稽查採樣之原始紀錄"],"a",
 "第69條第1項：事業、污水下水道系統應將主管機關核准之水污染防治許可證（文件）、依本法申報之資料，與環境工程技師、廢水處理專責人員及環境檢驗測定機構之證號資料，公開於中央主管機關指定之網站。第3項並定各級主管機關得於指定網站公開查核、處分之個別及統計資訊。",
 "What must enterprises publish on the website designated by the central authority?",
 ["Approved water pollution control permits and documents, data reported under this Act, and the licence numbers of engineers, dedicated personnel and testing organisations","Company registration documents, three years of financial statements, the shareholder register, raw material purchase lists, and licence numbers of personnel and testing bodies","Site layout and process flow diagrams, daily water and power records, the staff roster, product shipment volumes, and all plans and drawings certified by engineers","Fines imposed over the years with payment proof, appeal and litigation outcomes, remediation cost details, and the original records of every official sampling"],
 "Article 69, paragraphs 1 and 3."),

(W,"第70條",2,"水污法-受害人鑑定",
 "水污染受害人得向主管機關申請何事項？主管機關查明後應如何處理？",
 ["得申請鑑定其受害原因；主管機關得會同有關機關查明後，命排放水污染物者立即改善，受害人並得請求適當賠償","得申請補償金及醫療費用；主管機關應會同衛生機關查明後，逕由主管機關先行墊付賠償金額再向污染行為人求償","得申請免費健康檢查服務；主管機關應會同目的事業主管機關查明後，命排放水污染物者限期改善但不得請求賠償","得申請重新劃定水體分類；主管機關應會同水利機關查明後，公告調整該水體之水質標準並命污染行為人停工停業"],"a",
 "第70條：水污染受害人，得向主管機關申請鑑定其受害原因；主管機關得會同有關機關查明後，命排放水污染物者立即改善，受害人並得請求適當賠償。第71條另定地面水體發生污染事件時，主管機關應令污染行為人限期清除處理，屆期不為者得代為清除處理並求償必要費用。",
 "What may a victim of water pollution apply for, and what does the authority do after investigating?",
 ["Apply for determination of the cause of harm; after investigating with relevant agencies the authority orders immediate improvement, and the victim may claim proper compensation","Apply for compensation and medical costs; after investigating with health agencies the authority advances the compensation itself and then recovers it from the polluter","Apply for free health examinations; after investigating with industry authorities the authority orders improvement within a deadline but no compensation may be claimed","Apply for reclassification of the water body; after investigating with water agencies the authority adjusts the quality standard and suspends the polluter's operations"],
 "Article 70; see also Article 71."),

(W,"第71條",3,"水污法-代為清除",
 "地面水體發生污染事件時，主管機關應如何處理？其必要費用之求償權效力為何？",
 ["應令污染行為人限期清除處理，屆期不為清除處理時得代為清除處理，並向其求償清理、改善及衍生之必要費用；該求償權優於一切債權及抵押權","應令污染行為人限期清除處理，屆期不為清除處理時應移送司法機關偵辦，主管機關不得代為清除；該費用求償權與一般債權具有相同之受償順位","應由主管機關逕行代為清除處理後再通知污染行為人繳納費用，無須先令其限期清除；該求償權次於抵押權但優於一般無擔保之普通債權順位","應報請中央主管機關同意後始得代為清除處理並求償必要費用；該求償權須經法院判決確定後始生效力，且不得優先於其他債權或抵押權"],"a",
 "第71條第1項：地面水體發生污染事件，主管機關應令污染行為人限期清除處理，屆期不為清除處理時，主管機關得代為清除處理，並向其求償清理、改善及衍生之必要費用。第2項：前項必要費用之求償權，優於一切債權及抵押權。第71條之1並定主管機關得免提供擔保向行政法院聲請假扣押、假處分以保全該債權。",
 "How must the authority act on a surface water pollution incident, and what priority does its cost claim have?",
 ["Order the polluter to clean up within a deadline, act in its place if it fails, and recover cleanup, improvement and consequential costs; that claim outranks all claims and mortgages","Order the polluter to clean up within a deadline and refer the case to the judiciary if it fails, without acting in its place; the cost claim ranks equally with ordinary claims","Clean up directly and then bill the polluter, without first setting any deadline; the claim ranks below mortgages but above ordinary unsecured claims in priority","Obtain central approval before acting in the polluter's place and recovering costs; the claim takes effect only on a final judgment and never outranks other claims"],
 "Article 71, paragraphs 1 and 2; see also Article 71-1."),

(W,"第71條之1",3,"水污法-保全程序",
 "為保全主管機關代為清理之債權、所裁處之罰鍰及第六十六條之二追繳所得利益之履行，主管機關得如何處理？",
 ["得免提供擔保向行政法院聲請假扣押、假處分","應提供相當擔保後向普通法院聲請假扣押處分","應報請行政院核准後逕行查封債務人之財產","得逕行變賣債務人之生產設備以充抵應繳金額"],"a",
 "第71條之1：為保全第71條主管機關代為清理之債權、違反本法規定所裁處之罰鍰及第66條之2追繳所得利益之履行，主管機關得免提供擔保向行政法院聲請假扣押、假處分。此與第71條第2項該求償權優於一切債權及抵押權之規定，共同強化債權之保全。",
 "How may the authority secure its cleanup claims, fines and recovered gains?",
 ["It may apply to the administrative court for provisional attachment or injunction without providing security","It must provide adequate security and apply to the ordinary court for a provisional attachment order","It must obtain Executive Yuan approval and may then seize the debtor's property directly on its own","It may directly sell off the debtor's production equipment to offset the amounts that remain payable"],
 "Article 71-1; read with Article 71, paragraph 2."),

(W,"第72條",3,"水污法-公民訴訟",
 "主管機關疏於執行本法時，受害人民或公益團體得如何救濟？其等待期間為何？",
 ["得敘明疏於執行之具體內容以書面告知主管機關；主管機關於書面告知送達之日起六十日內仍未依法執行者，得以該主管機關為被告直接向高等行政法院提起訴訟","得敘明疏於執行之具體內容以書面告知主管機關；主管機關於書面告知送達之日起三十日內仍未依法執行者，得以該事業為被告直接向地方法院提起民事損害賠償訴訟","得直接向監察院陳情並請求彈劾失職人員；監察院於受理陳情之日起九十日內未為處理者，始得以該主管機關為被告向高等行政法院提起課予義務之訴訟","得敘明具體內容向上級機關提起訴願；上級機關於受理訴願之日起一百二十日內未為決定者，得以該主管機關為被告向最高行政法院直接提起撤銷之訴"],"a",
 "第72條第1項：事業、污水下水道系統違反本法或依本法授權訂定之相關命令而主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知主管機關；主管機關於書面告知送達之日起六十日內仍未依法執行者，得以該主管機關為被告，直接向高等行政法院提起訴訟，請求判令其執行。第2項並定法院得判命被告機關支付適當律師費用、監測鑑定費用予有具體貢獻之原告。",
 "How may citizens or public interest groups respond to lax enforcement, and how long must they wait?",
 ["Notify the authority in writing with specifics of the lax enforcement; if it still fails to act within sixty days of service, they may sue that authority in the High Administrative Court","Notify the authority in writing with specifics of the lax enforcement; if it still fails to act within thirty days of service, they may sue the enterprise for damages in the district court","Petition the Control Yuan directly and seek impeachment of the officials; only if it fails to act within ninety days may they sue the authority in the High Administrative Court","Lodge an appeal with the superior agency with specifics; if no decision issues within one hundred and twenty days, they may sue that authority in the Supreme Administrative Court"],
 "Article 72, paragraphs 1 and 2."),

(W,"第73條",3,"水污法-情節重大",
 "本法所稱情節重大，包括下列何種情形？",
 ["未經合法登記或許可之污染源違反本法規定、經處分後自報停工改善經查證非屬實、一年內經二次限期改善仍繼續違反本法規定","連續三年未依規定申報放流水水質水量檢驗測定結果、未依規定設置廢水處理專責人員、未將許可文件公開於中央指定之網站","排放水量每日超過五百立方公尺、位於水污染管制區內、廢水處理設施設置年限已逾十五年且未辦理功能評鑑及更新改善","未於期限內繳納水污染防治費逾九十日、經主管機關通知限期補正而逾期補正、放流口未依規定設置固定標示牌及編號"],"a",
 "第73條第1項列舉情節重大情形，包括：未經合法登記或許可之污染源違反本法規定；經處分後自報停工改善經查證非屬實；一年內經二次限期改善仍繼續違反本法規定；工業區內事業納管而違反下水道法令經通知停止使用仍繼續排放；大量排放污染物經認定嚴重影響附近水體品質；排放廢（污）水含有害健康物質經認定有危害公眾健康之虞；其他經認定嚴重影響附近地區水體品質之行為。",
 "Which of the following counts as a serious case under this Act?",
 ["A pollution source without lawful registration or permit breaching this Act, a falsely self reported shutdown after a penalty, or continuing breach after two improvement orders in one year","Failing to report effluent test results for three consecutive years, failing to appoint dedicated wastewater personnel, or not publishing permit documents on the designated website","Discharging over five hundred cubic metres daily, being located inside a water pollution control zone, or running treatment facilities over fifteen years old without upgrading","Leaving the pollution control fee unpaid for over ninety days, correcting only after the ordered deadline, or failing to post a fixed sign and number at the discharge outlet"],
 "Article 73, paragraph 1."),

(W,"第73條",3,"水污法-優惠待遇",
 "經認定情節重大之事業，其政府優惠待遇如何處理？優惠待遇包括哪些？",
 ["主管機關應公開該事業，由提供優惠待遇之機關停止並追回違規行為所屬年度之優惠待遇，其後三年內不得享受政府優惠待遇；優惠待遇包含獎勵、補助、捐助或減免之租稅、租金、費用等一切優惠措施","主管機關得公開該事業，並得視情節輕重停止其當年度優惠待遇但不予追回，其後一年內不得申請新增之優惠待遇；優惠待遇僅指中央政府所給予之各項獎勵金與補助款，不包含租稅減免","主管機關應公開該事業，並應通知其目的事業主管機關廢止其工廠登記，其後五年內不得重新申請設立登記；優惠待遇包含政府採購之投標資格及各類產業輔導計畫之參與資格","主管機關應將該事業移送司法機關偵辦，並由稅捐機關補徵其歷年減免之全部稅額，其後十年內不得享受優惠；優惠待遇僅指地方政府依自治條例所給予之各項租金與規費之減免"],"a",
 "第73條第2項：主管機關應公開依前項規定認定情節重大之事業，由提供優惠待遇之目的事業主管機關或各該法律之主管機關停止並追回其違規行為所屬年度之優惠待遇，並於其後三年內不得享受政府之優惠待遇。第3項：所稱優惠待遇包含中央或地方政府依法律或行政行為所給予該事業獎勵、補助、捐助或減免之租稅、租金、費用或其他一切優惠措施。",
 "How are government benefits treated for enterprises found to be serious violators, and what counts as benefits?",
 ["The authority publicises them, the granting agency stops and claws back that year's benefits, and no government benefit may be enjoyed for the next three years; benefits cover awards, subsidies, grants and any tax, rent or fee reduction","The authority may publicise them and may stop the current year's benefits without clawback, and no new benefit may be sought for one year; benefits mean only central government awards and subsidies and never tax reductions","The authority publicises them and asks the industry authority to revoke the factory registration, with no new registration for five years; benefits cover procurement bidding eligibility and industry guidance programme access","The authority refers them to the judiciary and the tax office recovers every tax previously reduced, with no benefits at all for ten years; benefits mean only the local rent and fee reductions granted under self government ordinances"],
 "Article 73, paragraphs 2 and 3."),

(W,"第74條",1,"水污法-施行細則",
 "水污染防治法施行細則由何機關訂定？",
 ["由中央主管機關定之","由行政院會商定之","由地方政府分別定之","由目的事業機關定之"],"a",
 "第74條：本法施行細則，由中央主管機關定之。本法多處授權中央主管機關訂定辦法或標準，例如第7條第2項放流水標準、第18條水污染防治措施管理辦法、第23條第2項檢驗測定機構管理辦法等。",
 "Who issues the Enforcement Rules of the Water Pollution Control Act?",
 ["The central competent authority","The Executive Yuan after consultation","Each local government separately","The industry competent authority"],
 "Article 74."),

(W,"第75條",1,"水污法-施行日",
 "水污染防治法之施行日期規定為何？",
 ["自公布日施行","自公布後六個月施行","由行政院定之","自公布後一年施行"],"a",
 "第75條：本法自公布日施行。本法最近一次修正日期為民國107年6月13日。相對地，其授權訂定之放流水標準第9條則規定除另定施行日期者外，自發布日施行。",
 "When does the Water Pollution Control Act take effect?",
 ["From the date of promulgation","Six months after promulgation","As set by the Executive Yuan","One year after its promulgation"],
 "Article 75."),
]
